**Scenario:** Several nodes each produce a partial `scores` dict.  
You want them **merged** — not overwritten — so all keys are preserved.

```
Node A returns: {"math": 85}
Node B returns: {"science": 90}
Node C returns: {"math": 95}     ← updates existing key

Final state:    {"math": 95, "science": 90}
```

```python
# ── Example 5: Custom reducer — merge dicts ────────────────────────

def merge_dicts(old: dict, new: dict) -> dict:
    """Merge two dicts; new values overwrite existing keys."""
    return {**old, **new}

class StudentState(TypedDict):
    scores: Annotated[dict, merge_dicts]  # ← custom reducer
    name:   str

def grade_math(state: StudentState):
    print("  grade_math    → {math: 85}")
    return {"scores": {"math": 85}}

def grade_science(state: StudentState):
    print("  grade_science → {science: 90}")
    return {"scores": {"science": 90}}

def grade_math_retry(state: StudentState):
    print("  grade_math_retry → {math: 95}  (updates existing 'math' key)")
    return {"scores": {"math": 95}}

def grade_english(state: StudentState):
    print("  grade_english → {english: 78}")
    return {"scores": {"english": 78}}

graph = StateGraph(StudentState)
graph.add_node("math",        grade_math)
graph.add_node("science",     grade_science)
graph.add_node("math_retry",  grade_math_retry)
graph.add_node("english",     grade_english)
graph.add_edge(START,        "math")
graph.add_edge("math",       "science")
graph.add_edge("science",    "math_retry")
graph.add_edge("math_retry", "english")
graph.add_edge("english",    END)
app = graph.compile()

result = app.invoke({"scores": {}, "name": "Alice"})
print(f"\nFinal scores: {result['scores']}")
print("Expected: {'math': 95, 'science': 90, 'english': 78}")
print("✓ merge_dicts reducer accumulated all subject scores, math updated to 95")
```

**Output**

```text
grade_math    → {math: 85}
  grade_science → {science: 90}
  grade_math_retry → {math: 95}  (updates existing 'math' key)
  grade_english → {english: 78}

Final scores: {'math': 95, 'science': 90, 'english': 78}
Expected: {'math': 95, 'science': 90, 'english': 78}
✓ merge_dicts reducer accumulated all subject scores, math updated to 95
```
